// Specification: ASSIGNMENT-ORDER-ORIGINAL-UPLOAD-001 v14, capability-last setup.
mysqli_report(MYSQLI_REPORT_ERROR|MYSQLI_REPORT_STRICT);
$host=getenv('FMONITOR_TEST_DB_HOST')?:'127.0.0.1';$port=(int)(getenv('FMONITOR_TEST_DB_PORT')?:23306);$user=getenv('FMONITOR_TEST_DB_ADMIN_USER')?:'root';$password=getenv('FMONITOR_TEST_DB_ADMIN_PASSWORD')?:'fmonitor2_test_root_local';$token=bin2hex(random_bytes(6));$admin=new mysqli($host,$user,$password,'',$port);$created=[];
$quote=static fn(string$value):string=>'`'.str_replace('`','``',$value).'`';
$newDb=static function(string$axis)use(&$created,$admin,$host,$port,$user,$password,$token,$quote):mysqli{$name="t_aoou_cap_{$axis}_{$token}";if(preg_match('/^t_aoou_cap_[a-z0-9_]+_[0-9a-f]{12}$/D',$name)!==1)throw new TestFailure('Unsafe capability database identity.');$admin->query('CREATE DATABASE '.$quote($name).' CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci');$created[]=$name;$db=new mysqli($host,$user,$password,$name,$port);$db->set_charset('utf8mb4');return$db;};
$prefix='cap_';
$prepareV4=static function(mysqli$db)use($prefix):void{FMonitor2\InstallationProcess\ProductionProcessSchemaMigration::apply($db,$prefix);FMonitor2\InstallationProcess\ProcessUserCapabilitiesSchemaMigration::apply($db,$prefix);FMonitor2\InstallationProcess\ProcessCommandCapabilitiesSchemaMigration::apply($db,$prefix);};
$capabilityClause=static function(mysqli$db)use($prefix):array{$table=$prefix.'fm2_process_user_capabilities';$statement=$db->prepare("SELECT CONSTRAINT_NAME,CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME=? AND CHECK_CLAUSE LIKE '%capability%in%'");$statement->bind_param('s',$table);$statement->execute();return$statement->get_result()->fetch_all(MYSQLI_ASSOC);};
$snapshot=static function(mysqli$db):string{$rows=$db->query("SELECT TABLE_NAME,ENGINE,TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() ORDER BY BINARY TABLE_NAME")->fetch_all(MYSQLI_ASSOC);$checks=$db->query("SELECT TABLE_NAME,CONSTRAINT_NAME,CHECK_CLAUSE FROM information_schema.CHECK_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() ORDER BY BINARY TABLE_NAME,BINARY CONSTRAINT_NAME")->fetch_all(MYSQLI_ASSOC);return json_encode([$rows,$checks],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);};
$v4="capability IN ('assignment_order.prepare','assignment_order.confirm_registration','installation.open','construction_control_engineer')";$v5="capability IN ('assignment_order.prepare','assignment_order.confirm_registration','installation.open','construction_control_engineer','assignment_order.original.upload','assignment_order.original.correct')";
$replaceCapability=static function(mysqli$db,string$expression,string$name='candidate')use($prefix,$capabilityClause):void{$rows=$capabilityClause($db);foreach($rows as$row){$constraint=$row['CONSTRAINT_NAME'];if(preg_match('/^[A-Za-z0-9_$]{1,64}$/D',$constraint)!==1)continue;$db->query("ALTER TABLE `{$prefix}fm2_process_user_capabilities` DROP CONSTRAINT `{$constraint}`");}$db->query("ALTER TABLE `{$prefix}fm2_process_user_capabilities` ADD CONSTRAINT `{$name}` CHECK ({$expression})");};

$probe=$newDb('probe');try{assertSameValue('1',(string)$probe->query('SELECT 1 ready')->fetch_assoc()['ready'],'Capability verifier MariaDB preflight is live.');if(!class_exists(AssignmentOrderOriginalSchemaMigrationVerificationFactory::class))throw new TestFailure('INTENDED_RED: approved AssignmentOrderOriginalSchemaMigrationVerificationFactory seam is absent.');require dirname(__DIR__).'/Support/AssignmentOrderOriginalSchemaMigrationObserverSpy.php';
    $v4db=$newDb('v4');$prepareV4($v4db);$result=AssignmentOrderOriginalSchemaMigration::apply($v4db,$prefix);assertSameValue(AssignmentOrderOriginalSchemaMigrationStatus::APPLIED,$result->status(),'Exact V4 upgrades to V5.');assertSameValue([...Contract::TABLES,'fm2_process_user_capabilities'],$result->affectedTables(),'V4 result publishes schema then capability.');$repeat=AssignmentOrderOriginalSchemaMigration::apply($v4db,$prefix);assertSameValue([AssignmentOrderOriginalSchemaMigrationStatus::UNCHANGED,[]],[$repeat->status(),$repeat->affectedTables()],'Exact V5 repeat unchanged.');assertSameValue(true,str_contains($capabilityClause($v4db)[0]['CHECK_CLAUSE'],'assignment_order.original.correct'),'Fresh schema read proves exact V5 correct grant.');$v4db->close();
    $variants=['upload_only'=>"capability IN ('assignment_order.prepare','assignment_order.confirm_registration','installation.open','construction_control_engineer','assignment_order.original.upload')",'correct_only'=>"capability IN ('assignment_order.prepare','assignment_order.confirm_registration','installation.open','construction_control_engineer','assignment_order.original.correct')",'superset'=>"capability IN ('assignment_order.prepare','assignment_order.confirm_registration','installation.open','construction_control_engineer','assignment_order.original.upload','assignment_order.original.correct','unexpected')",'subset'=>"capability IN ('assignment_order.prepare','construction_control_engineer')"];
    foreach($variants as$axis=>$expression){$db=$newDb($axis);$prepareV4($db);$replaceCapability($db,$expression);$before=$snapshot($db);$result=AssignmentOrderOriginalSchemaMigration::apply($db,$prefix);assertSameValue(AssignmentOrderOriginalSchemaMigrationStatus::CONFLICT,$result->status(),"{$axis} capability conflicts.");assertSameValue(['fm2_process_user_capabilities'],$result->affectedTables(),"{$axis} exact affected table.");assertSameValue($before,$snapshot($db),"{$axis} performs zero DDL.");$db->close();}
    $multiple=$newDb('multiple');$prepareV4($multiple);$multiple->query("ALTER TABLE `{$prefix}fm2_process_user_capabilities` ADD CONSTRAINT `second_candidate` CHECK ({$v4})");$before=$snapshot($multiple);$result=AssignmentOrderOriginalSchemaMigration::apply($multiple,$prefix);assertSameValue([AssignmentOrderOriginalSchemaMigrationStatus::CONFLICT,['fm2_process_user_capabilities']],[$result->status(),$result->affectedTables()],'Multiple candidates conflict.');assertSameValue($before,$snapshot($multiple),'Multiple candidate conflict zero DDL.');$multiple->close();
    $unsafe=$newDb('unsafe');$prepareV4($unsafe);$replaceCapability($unsafe,$v4,'unsafe-name');$before=$snapshot($unsafe);$result=AssignmentOrderOriginalSchemaMigration::apply($unsafe,$prefix);assertSameValue([AssignmentOrderOriginalSchemaMigrationStatus::CONFLICT,['fm2_process_user_capabilities']],[$result->status(),$result->affectedTables()],'Unsafe candidate name conflicts.');assertSameValue($before,$snapshot($unsafe),'Unsafe-name conflict zero DDL.');$unsafe->close();
    foreach(Contract::TABLES as$index=>$logicalTable){$db=$newDb('create_'.$index);$prepareV4($db);$observer=new AssignmentOrderOriginalSchemaMigrationObserverSpy(AssignmentOrderOriginalSchemaMigrationPhase::AFTER_SCHEMA_TABLE_CREATED,$logicalTable);$application=AssignmentOrderOriginalSchemaMigrationVerificationFactory::create($observer);try{$application->apply($db,$prefix);throw new TestFailure("Fault after {$logicalTable} must be unavailable.");}catch(AssignmentOrderOriginalSchemaMigrationUnavailable$error){assertSameValue(['AssignmentOrderOriginalSchemaMigrationUnavailable',0,null],[$error->getMessage(),$error->getCode(),$error->getPrevious()],"{$logicalTable} fixed unavailable.");}assertSameValue(false,str_contains($capabilityClause($db)[0]['CHECK_CLAUSE'],'assignment_order.original.upload'),"{$logicalTable} partial keeps V4.");$recovery=AssignmentOrderOriginalSchemaMigration::apply($db,$prefix);assertSameValue(AssignmentOrderOriginalSchemaMigrationStatus::APPLIED,$recovery->status(),"{$logicalTable} leading partial safely recovers.");$db->close();}
    $preAlter=$newDb('pre_alter');$prepareV4($preAlter);$application=AssignmentOrderOriginalSchemaMigrationVerificationFactory::create(new AssignmentOrderOriginalSchemaMigrationObserverSpy(AssignmentOrderOriginalSchemaMigrationPhase::AFTER_SCHEMA_REVALIDATED_BEFORE_CAPABILITIES,null));try{$application->apply($preAlter,$prefix);throw new TestFailure('Pre-ALTER fault must be unavailable.');}catch(AssignmentOrderOriginalSchemaMigrationUnavailable$error){assertSameValue('AssignmentOrderOriginalSchemaMigrationUnavailable',$error->getMessage(),'Pre-ALTER fixed unavailable.');}assertSameValue(false,str_contains($capabilityClause($preAlter)[0]['CHECK_CLAUSE'],'assignment_order.original.upload'),'Pre-ALTER observer preserves V4.');assertSameValue(AssignmentOrderOriginalSchemaMigrationStatus::APPLIED,AssignmentOrderOriginalSchemaMigration::apply($preAlter,$prefix)->status(),'Pre-ALTER retry safely publishes V5.');$preAlter->close();
    $postAlter=$newDb('post_alter');$prepareV4($postAlter);$application=AssignmentOrderOriginalSchemaMigrationVerificationFactory::create(new AssignmentOrderOriginalSchemaMigrationObserverSpy(AssignmentOrderOriginalSchemaMigrationPhase::AFTER_CAPABILITY_ALTER_BEFORE_REVALIDATION,null));$post=$application->apply($postAlter,$prefix);assertSameValue(AssignmentOrderOriginalSchemaMigrationStatus::APPLIED,$post->status(),'Post-ALTER fault resolves by fresh exact V5 read.');assertSameValue([...Contract::TABLES,'fm2_process_user_capabilities'],$post->affectedTables(),'Post-ALTER resolved result reports durable publications.');assertSameValue(AssignmentOrderOriginalSchemaMigrationStatus::UNCHANGED,AssignmentOrderOriginalSchemaMigration::apply($postAlter,$prefix)->status(),'Post-ALTER safe retry unchanged.');$postAlter->close();
    fwrite(STDOUT,"ASSIGNMENT_ORDER_ORIGINAL_CAPABILITY_MIGRATION_001_OK\n");
}finally{$probe->close();foreach(array_reverse($created)as$name){try{$admin->query('DROP DATABASE '.$quote($name));}catch(Throwable){}}$admin->close();}
